//! The greeter gRPC service: the protobuf boundary of the greeting use case.

use std::sync::Arc;

use my_service_container::Container;
use my_service_domain::errors::GreeterError;
use my_service_domain::use_cases::{HelloRequest, HelloResponse, HelloUseCase};
use proto::greeter_server;
use proto::{HelloReply, HelloRequest as ProtoHelloRequest};
use tonic::{Request, Response, Status};

// The service trait generated by `tonic-build` returns `Result<Response<_>, Status>` through an
// `async_trait` desugaring; the signatures are fixed by the protobuf contract, so the lints
// that fire on the generated code are allowed here and nowhere else.
#[allow(clippy::result_large_err, clippy::double_must_use)]
mod proto {
    tonic::include_proto!("greeter");
}

/// Register the greeter service on a fresh [`GreeterService`] sharing the application
/// dependencies.
pub fn service(container: Arc<Container>) -> greeter_server::GreeterServer<GreeterService> {
    greeter_server::GreeterServer::new(GreeterService::new(container))
}

/// Serves the greeter RPCs: runs the greeting use case behind the protobuf boundary.
#[derive(Debug)]
pub struct GreeterService {
    hello_use_case: Arc<HelloUseCase>,
}

impl GreeterService {
    /// Bind the service to the shared application dependencies.
    pub fn new(container: Arc<Container>) -> Self {
        GreeterService {
            hello_use_case: container.hello_use_case.clone(),
        }
    }
}

/// Convert the protobuf request into the use-case request model.
impl From<ProtoHelloRequest> for HelloRequest {
    fn from(request: ProtoHelloRequest) -> Self {
        HelloRequest { name: request.name }
    }
}

/// Convert the use-case response model into the protobuf reply.
impl From<HelloResponse> for HelloReply {
    fn from(response: HelloResponse) -> Self {
        HelloReply {
            message: response.message,
        }
    }
}

/// Map an application error onto the gRPC status the clients expect.
fn to_status(error: GreeterError) -> Status {
    match error {
        GreeterError::InvalidNameLength => Status::invalid_argument(error.to_string()),
    }
}

#[tonic::async_trait]
impl greeter_server::Greeter for GreeterService {
    async fn hello(
        &self,
        request: Request<ProtoHelloRequest>,
    ) -> Result<Response<HelloReply>, Status> {
        let response = self
            .hello_use_case
            .execute(request.into_inner().into())
            .map_err(to_status)?;
        Ok(Response::new(response.into()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn service() -> GreeterService {
        GreeterService::new(Arc::new(Container::new()))
    }

    #[tokio::test]
    async fn hello_greets_the_requested_name() {
        let reply = greeter_server::Greeter::hello(
            &service(),
            Request::new(ProtoHelloRequest {
                name: "Alice".into(),
            }),
        )
        .await
        .unwrap()
        .into_inner();

        assert_eq!(reply.message, "Hello, Alice!");
    }

    #[tokio::test]
    async fn hello_rejects_a_name_shorter_than_three_bytes() {
        let status = greeter_server::Greeter::hello(
            &service(),
            Request::new(ProtoHelloRequest { name: "ab".into() }),
        )
        .await
        .unwrap_err();

        assert_eq!(status.code(), tonic::Code::InvalidArgument);
        assert_eq!(status.message(), "Invalid name length");
    }
}
